def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        for j, val in enumerate(row):
            if val == x:
                result.append((i, j))
    # Sort by row ascending, then by column descending
    result.sort(key=lambda t: (t[0], -t[1]))
    return result
